const html = $input.first().json.data;
const jobs = [];

if (!html) {
  return [{ json: { error: 'No HTML received from LinkedIn', jobs: [] } }];
}

// Split into individual <li> job card blocks
const liBlocks = html.split(/<\/li>/);

for (const block of liBlocks) {
  if (!block.includes('base-card')) continue;

  // Job title
  const titleMatch = block.match(/class="[^"]*base-search-card__title[^"]*"[^>]*>[\s]*([^<]+)[\s]*<\/h3>/);
  const title = titleMatch ? titleMatch[1].trim() : null;
  if (!title) continue;

  // Company name
  const companyMatch = block.match(/class="[^"]*base-search-card__subtitle[^"]*"[^>]*>[\s]*(?:<[^>]+>[\s]*)*([^<]+)[\s]*<\//);
  const company = companyMatch ? companyMatch[1].trim() : 'Unknown';

  // Location
  const locationMatch = block.match(/class="[^"]*job-search-card__location[^"]*"[^>]*>[\s]*([^<]+)[\s]*<\/span>/);
  const location = locationMatch ? locationMatch[1].trim() : 'Unknown';

  // Posted date (ISO datetime attribute)
  const dateMatch = block.match(/datetime="([^"]+)"/);
  const postedDate = dateMatch ? dateMatch[1] : null;

  // Relative time label (e.g. "2 days ago")
  const relTimeMatch = block.match(/class="[^"]*job-search-card__listdate[^"]*"[^>]*>([^<]+)<\/time>/);
  const relativeTime = relTimeMatch ? relTimeMatch[1].trim() : null;

  // Job URL
  const urlMatch = block.match(/href="(https:\/\/[^"]*linkedin\.com\/jobs\/view\/[^"?]+)/);
  const jobUrl = urlMatch ? urlMatch[1].split('?')[0] : null;

  // Job ID from URL
  const idMatch = jobUrl ? jobUrl.match(/view\/(\d+)/) : null;
  const jobId = idMatch ? idMatch[1] : null;

  // Employment type / benefits badge
  const benefitsMatch = block.match(/class="[^"]*job-search-card__benefits[^"]*"[^>]*>([^<]+)<\//);
  const employmentType = benefitsMatch ? benefitsMatch[1].trim() : null;

  jobs.push({
    json: {
      job_id: jobId,
      title,
      company,
      location,
      employment_type: employmentType,
      posted_date: postedDate,
      relative_time: relativeTime,
      job_url: jobUrl,
      source: 'LinkedIn'
    }
  });
}

if (jobs.length === 0) {
  return [{
    json: {
      message: 'No jobs parsed. LinkedIn may be rate-limiting this request or the page structure has changed.',
      html_length: html.length,
      jobs: []
    }
  }];
}

return jobs;
